declare_lint ! { # [doc = " The `dangling_pointers_from_temporaries` lint detects getting a pointer to data"] # [doc = " of a temporary that will immediately get dropped."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " # unsafe fn use_data(ptr: *const u8) { }"] # [doc = " fn gather_and_use(bytes: impl Iterator<Item = u8>) {"] # [doc = "     let x: *const u8 = bytes.collect::<Vec<u8>>().as_ptr();"] # [doc = "     unsafe { use_data(x) }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Getting a pointer from a temporary value will not prolong its lifetime,"] # [doc = " which means that the value can be dropped and the allocation freed"] # [doc = " while the pointer still exists, making the pointer dangling."] # [doc = " This is not an error (as far as the type system is concerned)"] # [doc = " but probably is not what the user intended either."] # [doc = ""] # [doc = " If you need stronger guarantees, consider using references instead,"] # [doc = " as they are statically verified by the borrow-checker to never dangle."] pub DANGLING_POINTERS_FROM_TEMPORARIES , Warn , "detects getting a pointer from a temporary" }